// Helper to get questions by category/grade/tier
export function getQuestions({ skill_category, base_grade, difficulty_tier, limit = 5 }) {
  let filtered = QUESTIONS.filter(q => {
    if (skill_category && q.skill_category !== skill_category) return false;
    if (base_grade && q.base_grade !== base_grade) return false;
    if (difficulty_tier && q.difficulty_tier !== difficulty_tier) return false;
    return true;
  });
  // Shuffle
  filtered = filtered.sort(() => 0.5 - Math.random());
  return filtered.slice(0, limit);
}

